import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.StringTokenizer; import java.util.TreeMap; import java.util.Map; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine().trim()); while (t-- > 0) { int n = Integer.parseInt(br.readLine().trim()); int[] x = new int[n]; int[] y = new int[n]; int[] h = new int[n]; int[] diffs = new int[n]; TreeMap<Integer, Long> map = new TreeMap<>(); for (int i = 0; i < n; i++) { StringTokenizer st = new StringTokenizer(br.readLine()); x[i] = Integer.parseInt(st.nextToken()); y[i] = Integer.parseInt(st.nextToken()); h[i] = Integer.parseInt(st.nextToken()); diffs[i] = y[i] - x[i]; map.put(diffs[i], map.getOrDefault(diffs[i], 0L) + h[i]); } boolean found = false; long totalPeople = 0; for (long val : map.values()) totalPeople += val; long leftSum = 0; for (Map.Entry<Integer, Long> entry : map.entrySet()) { long currentOnLine = entry.getValue(); long rightSum = totalPeople - leftSum - currentOnLine; if (leftSum == rightSum) { found = true; break; } leftSum += currentOnLine; } if (found) System.out.println("YES"); else System.out.println("NO"); } } }